package com.zxl.zxlaiagent.knowledge.scoped;
import com.zxl.zxlaiagent.knowledge.*;
import com.zxl.zxlaiagent.security.*;
import java.time.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class ScopedKnowledgePgTest {
 SecurityDatabase security; KnowledgeDatabase db; AuthenticationService auth; AuthorizationService authorization; String a,b; ActorRef alice,bob; ScopedKnowledgeFactory factory;
 @BeforeEach void setup(){security=SecurityDatabase.fromEnvironment();db=new KnowledgeDatabase(System.getenv("LESSON12_DB_URL"),System.getenv("LESSON12_DB_USER"),System.getenv("LESSON12_DB_PASSWORD"));auth=new AuthenticationService(security);authorization=new AuthorizationService(security);a="scope-"+java.util.UUID.randomUUID();b="scope-"+java.util.UUID.randomUUID();auth.provision(a,a,"synthetic-password",a,"knowledge-maintainer");auth.provision(b,b,"synthetic-password",b,"knowledge-maintainer");alice=auth.login(a,"synthetic-password",a).actor().ref();bob=auth.login(b,"synthetic-password",b).actor().ref();factory=new ScopedKnowledgeFactory(db,authorization,new DemoKnowledgeEmbedding(),com.zxl.zxlaiagent.knowledge.retrieval.Reranker.rules(),null,Clock.systemUTC());}
 @AfterEach void cleanup(){db.tx(c->{for(String tenant:java.util.List.of(a,b)){try(var s=KnowledgeDatabase.statement(c,"DELETE FROM confirmed_memory_history WHERE memory_id IN (SELECT memory_id FROM confirmed_memory WHERE tenant_id=?)",tenant)){s.executeUpdate();}try(var s=KnowledgeDatabase.statement(c,"DELETE FROM confirmed_memory WHERE tenant_id=?",tenant)){s.executeUpdate();}try(var s=KnowledgeDatabase.statement(c,"DELETE FROM knowledge_chunk WHERE tenant_id=?",tenant)){s.executeUpdate();}try(var s=KnowledgeDatabase.statement(c,"DELETE FROM knowledge_revision WHERE tenant_id=?",tenant)){s.executeUpdate();}try(var s=KnowledgeDatabase.statement(c,"DELETE FROM knowledge_document WHERE tenant_id=?",tenant)){s.executeUpdate();}}return null;});security.tx(c->{for(String id:java.util.List.of(a,b)){try(var s=SecurityDatabase.statement(c,"DELETE FROM authorization_audit WHERE subject_id=?",id)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"DELETE FROM subject WHERE subject_id=?",id)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"DELETE FROM tenant WHERE tenant_id=?",id)){s.executeUpdate();}}return null;});}
 @Test void actorScopesRawRetrievalAndMemory(){factory.knowledge(alice).importDocument("same","a.md","alpha private secret");factory.knowledge(bob).importDocument("same","b.md","beta private secret");assertEquals("alpha private secret",factory.knowledge(alice).detail("same").rawText());assertEquals("beta private secret",factory.knowledge(bob).detail("same").rawText());assertTrue(factory.retrieval(alice).retrieve(new com.zxl.zxlaiagent.knowledge.retrieval.RetrievalService.Request("beta","keyword",5,5,false,false,5000)).hits().isEmpty());assertEquals(a,factory.memory(alice).scope().userId());auth.revoke(alice);assertThrows(SecurityFailure.class,()->factory.knowledge(alice).list());}
 @Test void revocationDuringEmbeddingDoesNotHoldGateOrPublish()throws Exception{var started=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);KnowledgeEmbedding slow=text->{started.countDown();try{assertTrue(release.await(10,java.util.concurrent.TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}return new DemoKnowledgeEmbedding().embed(text);};var scoped=new ScopedKnowledgeFactory(db,authorization,slow,com.zxl.zxlaiagent.knowledge.retrieval.Reranker.rules(),null,Clock.systemUTC());var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try{var pending=pool.submit(()->scoped.knowledge(alice).importDocument("same","a.md","unpublished secret"));assertTrue(started.await(10,java.util.concurrent.TimeUnit.SECONDS));auth.revoke(alice);release.countDown();assertThrows(java.util.concurrent.ExecutionException.class,()->pending.get(10,java.util.concurrent.TimeUnit.SECONDS));assertTrue(new KnowledgeService(db,a,new DemoKnowledgeEmbedding()).list().stream().allMatch(m->m.activeRevision()==null));}finally{release.countDown();pool.shutdownNow();}}

 @Test void memorySourcesRequireOwnedConversationAndExactUserMessage(){
  var repository=org.mockito.Mockito.mock(com.zxl.zxlaiagent.conversation.repository.ConversationRepository.class);var id=java.util.UUID.randomUUID();var run=java.util.UUID.randomUUID();var message=com.zxl.zxlaiagent.conversation.model.MessageRecord.user(run,"我偏好英文回复",Instant.now());
  var conversation=new com.zxl.zxlaiagent.conversation.model.Conversation(id,"synthetic",Instant.now(),Instant.now(),0,java.util.List.of(message),java.util.List.of(com.zxl.zxlaiagent.conversation.model.RunRecord.started(run,Instant.now())),"knowledge");org.mockito.Mockito.when(repository.find(id)).thenReturn(java.util.Optional.of(conversation));authorization.registerResource(alice,new ResourceRef("conversation",id.toString()));
  var scoped=new ScopedKnowledgeFactory(db,authorization,new DemoKnowledgeEmbedding(),com.zxl.zxlaiagent.knowledge.retrieval.Reranker.rules(),null,Clock.systemUTC(),repository);
  assertThrows(SecurityFailure.class,()->scoped.memory(bob).propose(id.toString(),message.messageId().toString(),message.content(),600));
  assertThrows(SecurityFailure.class,()->scoped.memory(alice).propose(id.toString(),message.messageId().toString(),"我偏好中文回复",600));
  var proposed=scoped.memory(alice).propose(id.toString(),message.messageId().toString(),message.content(),600);scoped.memory(alice).confirm(proposed.id(),proposed.version());assertEquals("en",scoped.memory(alice).recall(1000,Duration.ofSeconds(2)).facts().get(0).value());assertTrue(scoped.memory(bob).list().isEmpty());assertThrows(java.util.NoSuchElementException.class,()->scoped.memory(bob).delete(proposed.id(),2));
  assertThrows(SecurityFailure.class,()->scoped.answer(bob).answer(new com.zxl.zxlaiagent.knowledge.answer.AnswerService.Request("policy",id.toString(),"demo",10000,null)));
  assertThrows(IllegalArgumentException.class,()->scoped.answer(alice).answer(new com.zxl.zxlaiagent.knowledge.answer.AnswerService.Request("policy",id.toString(),"demo",10000,"alice")));
 }
 @Test void answersUseActorEvidenceAndSubjectMemory(){
  String id=java.util.UUID.randomUUID().toString();authorization.registerResource(alice,new ResourceRef("conversation",id));factory.knowledge(alice).importDocument("same","a.md","The alpha policy is confidential.");factory.knowledge(bob).importDocument("same","b.md","The beta policy is confidential.");
  var response=factory.answer(alice).answer(new com.zxl.zxlaiagent.knowledge.answer.AnswerService.Request("alpha policy",id,"demo",10000,null));assertFalse(response.evidence().isEmpty());assertTrue(response.evidence().stream().allMatch(e->e.text().contains("alpha")));assertFalse(response.answer().contains("beta"));
  var reopened=new ScopedKnowledgeFactory(new KnowledgeDatabase(System.getenv("LESSON12_DB_URL"),System.getenv("LESSON12_DB_USER"),System.getenv("LESSON12_DB_PASSWORD")),new AuthorizationService(SecurityDatabase.fromEnvironment()),new DemoKnowledgeEmbedding(),com.zxl.zxlaiagent.knowledge.retrieval.Reranker.rules(),null,Clock.systemUTC());assertEquals("The alpha policy is confidential.",reopened.knowledge(alice).detail("same").rawText());
 }

 @Test void authorityLengthAndUnicodeScopesRemainValidAfterMigration(){
  String subject="主体"+"长".repeat(112)+java.util.UUID.randomUUID().toString();String tenant="租户"+"长".repeat(112)+java.util.UUID.randomUUID().toString();assertEquals(150,subject.length());assertEquals(150,tenant.length());auth.provision(subject,subject,"synthetic-password",tenant,"knowledge-maintainer");var actor=auth.login(subject,"synthetic-password",tenant).actor().ref();
  try{String document="d".repeat(120);factory.knowledge(actor).importDocument(document,"unicode.md","unicode authorized policy");assertEquals(document,factory.knowledge(actor).list().get(0).documentId());assertEquals(subject,factory.memory(actor).scope().userId());assertTrue(factory.memory(actor).list().isEmpty());db.tx(c->{try(var st=c.prepareStatement("SELECT count(*) FROM information_schema.columns WHERE table_schema='lesson12' AND column_name IN ('tenant_id','user_id') AND character_maximum_length=150");var rows=st.executeQuery()){rows.next();assertEquals(5,rows.getInt(1));}return null;});}
  finally{db.tx(c->{for(String table:java.util.List.of("knowledge_chunk","knowledge_revision","knowledge_document")){try(var st=KnowledgeDatabase.statement(c,"DELETE FROM "+table+" WHERE tenant_id=?",tenant)){st.executeUpdate();}}return null;});security.tx(c->{try(var st=SecurityDatabase.statement(c,"DELETE FROM authorization_audit WHERE subject_id=?",subject)){st.executeUpdate();}try(var st=SecurityDatabase.statement(c,"DELETE FROM subject WHERE subject_id=?",subject)){st.executeUpdate();}try(var st=SecurityDatabase.statement(c,"DELETE FROM tenant WHERE tenant_id=?",tenant)){st.executeUpdate();}return null;});}
 }

 @Test void actualHttpEmbeddingWaitDoesNotHoldEpochGate()throws Exception{
  var started=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.createContext("/embeddings",exchange->{exchange.getRequestBody().readAllBytes();started.countDown();try{release.await(10,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}byte[] bytes="{\"data\":[{\"embedding\":[0.1,0.2,0.3]}]}".getBytes(java.nio.charset.StandardCharsets.UTF_8);try{exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);}finally{exchange.close();}});server.start();var pool=java.util.concurrent.Executors.newSingleThreadExecutor();
  try{var embedding=new HttpKnowledgeEmbedding(java.net.URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/embeddings"),"synthetic-test-key","fixture","v1",3);var scoped=new ScopedKnowledgeFactory(db,authorization,embedding,com.zxl.zxlaiagent.knowledge.retrieval.Reranker.rules(),null,Clock.systemUTC());var future=pool.submit(()->scoped.knowledge(alice).importDocument("http","h.md","private pending embedding"));assertTrue(started.await(10,java.util.concurrent.TimeUnit.SECONDS));auth.revoke(alice);release.countDown();assertThrows(java.util.concurrent.ExecutionException.class,()->future.get(10,java.util.concurrent.TimeUnit.SECONDS));assertTrue(new KnowledgeService(db,a,embedding).list().stream().allMatch(m->m.activeRevision()==null));}
  finally{release.countDown();pool.shutdownNow();server.stop(0);}
 }

 @Test void sameTenantEmployeeReadsKnowledgeButOnlyOwnMemory(){
  String employee=a+"-employee";auth.provision(employee,employee,"synthetic-password",a,"employee");var actor=auth.login(employee,"synthetic-password",a).actor().ref();try{factory.knowledge(alice).importDocument("shared","s.md","shared tenant policy");assertEquals(1,factory.knowledge(actor).list().size());assertThrows(SecurityFailure.class,()->factory.knowledge(actor).importDocument("forbidden","f.md","denied"));
   var fixture=new com.zxl.zxlaiagent.knowledge.memory.MemoryService(db,new com.zxl.zxlaiagent.knowledge.memory.MemoryService.Scope(a,employee),Clock.systemUTC());var memory=fixture.propose("fixture-source","fixture-message","我偏好中文回复",600);fixture.confirm(memory.id(),memory.version());assertEquals(1,factory.memory(actor).list().size());assertTrue(factory.memory(alice).list().isEmpty());assertThrows(java.util.NoSuchElementException.class,()->factory.memory(alice).delete(memory.id(),2));
  }finally{security.tx(c->{try(var st=SecurityDatabase.statement(c,"DELETE FROM authorization_audit WHERE subject_id=?",employee)){st.executeUpdate();}try(var st=SecurityDatabase.statement(c,"DELETE FROM subject WHERE subject_id=?",employee)){st.executeUpdate();}return null;});}
 }
}
